+  Rodolphe: {fond:"#2F4FC9", initiale:"R"},
+  Labo:     {fond:"#C9CED7", motif:'<g stroke="#3A414D" stroke-width="1.7" fill="none" stroke-linejoin="round"><path d="M13.5 8h5M14.5 8v5.5L9.5 23a1.2 1.2 0 0 0 1 1.8h11a1.2 1.2 0 0 0 1-1.8l-5-9.5V8"/><path d="M11.6 19.5h8.8" stroke-width="1.4"/></g>'},
+};
+const SVG_NS = "http://www.w3.org/2000/svg";
+function avatarDe(nom){
+  nom = nom || "?";
+  const cle = nom in AVATARS ? nom : Object.keys(AVATARS).find(k => nom.toLowerCase().startsWith(k.toLowerCase()));
+  const a = cle ? AVATARS[cle] : {fond:"#8A919C", initiale: nom.trim().charAt(0).toUpperCase() || "?"};
+  const svg = document.createElementNS(SVG_NS, "svg");
+  svg.setAttribute("viewBox", "0 0 32 32"); svg.setAttribute("aria-hidden", "true");
+  svg.innerHTML = `<circle cx="16" cy="16" r="16" fill="${a.fond}"/>` + (a.motif || "");
+  if(a.initiale){                                   // texte posé par le DOM : un nom inconnu n'injecte rien
+    const t = document.createElementNS(SVG_NS, "text");
+    for(const [k, v] of Object.entries({x:16, y:21.5, "text-anchor":"middle", "font-size":15, "font-weight":700, fill:"#fff", "font-family":"Segoe UI, system-ui, sans-serif"})) t.setAttribute(k, v);
+    t.textContent = a.initiale; svg.append(t);
+  }
+  return el("span", {class:"avatar", title:nom}, svg);
+}
+// pendant que la voix lit un tour, l'avatar de celui qui parle pulse
+let voixEnCours = null;                             // {auteur, n} du tour lu à voix haute
+function marquerParleur(){
+  const z = $("conversation");
+  for(const a of z.querySelectorAll(".avatar.parle")) a.classList.remove("parle");
+  if(!voixEnCours) return;
+  const lignes = [...z.querySelectorAll(".ligne")];
+  const ligne = lignes.find(l => l.dataset.n === String(voixEnCours.n)) || lignes.filter(l => l.dataset.auteur === voixEnCours.auteur).pop();
+  ligne?.querySelector(".avatar")?.classList.add("parle");
+}
